mapper.update:
UPDATE device_work_period
SET end_at = #{endAt}
WHERE id = #{id} AND end_at IS NULL

mapper.select:
SELECT id, device_id, device_name, floor_name, start_at, end_at
FROM device_work_period
WHERE device_id = #{deviceId}
  AND start_at < #{endAt}
  AND (end_at IS NULL OR end_at > #{startAt})
ORDER BY start_at ASC
